import json
from collections import Counter

# Toy Cowrie-style JSON lines (made up; real files have thousands)
log = """\
{"eventid":"cowrie.login.failed","src_ip":"198.51.100.7","username":"root","password":"123456"}
{"eventid":"cowrie.login.failed","src_ip":"198.51.100.7","username":"root","password":"admin"}
{"eventid":"cowrie.login.failed","src_ip":"203.0.113.20","username":"admin","password":"admin"}
{"eventid":"cowrie.login.failed","src_ip":"203.0.113.20","username":"root","password":"123456"}
{"eventid":"cowrie.login.failed","src_ip":"192.0.2.99","username":"ubuntu","password":"ubuntu"}
{"eventid":"cowrie.login.success","src_ip":"192.0.2.99","username":"root","password":"Passw0rd"}
{"eventid":"cowrie.command.input","src_ip":"192.0.2.99","input":"uname -a"}
{"eventid":"cowrie.login.failed","src_ip":"198.51.100.7","username":"pi","password":"raspberry"}"""

events = [json.loads(line) for line in log.splitlines()]
logins = [e for e in events if e["eventid"].startswith("cowrie.login")]
print("sources:  ", len({e["src_ip"] for e in events}))
print("users:    ", Counter(e["username"] for e in logins).most_common(3))
print("passwords:", Counter(e["password"] for e in logins).most_common(3))
print("commands: ", [e["input"] for e in events
                     if e["eventid"] == "cowrie.command.input"])

breached = {"123456", "admin", "raspberry"}       # stand-in for a breach list
unique = {e["password"] for e in logins}
print(f"in breach list: {len(unique & breached)}/{len(unique)}")

from math import comb

def p_hit(real, decoys, touched):
    """Chance an intruder who touches `touched` hosts picked at random
    (no repeats) touches at least one decoy."""
    total = real + decoys
    return 1 - comb(real, touched) / comb(total, touched)

for decoys in (1, 5, 10, 50):
    row = [f"{p_hit(50, decoys, n):.1%}" for n in (3, 5, 10)]
    print(f"50 real + {decoys:2d} decoys, touch 3/5/10 hosts:", " ".join(row))
